import math

k = 2310
alpha_sqrt2 = math.sqrt(2)
alpha_pi = math.pi

def check_pretty(alpha, m, n, k):
    """Checks if (m, n) is a pretty pair for a given alpha and k."""
    # Calculate m * ceil(n * alpha) - n * floor(m * alpha)
    try:
        lhs = m * math.ceil(n * alpha) - n * math.floor(m * alpha)
        return lhs, lhs == k
    except OverflowError:
        return None, False

print(f"--- Testing with alpha = sqrt(2) ---")
results_sqrt2 = []
for m in range(1, 11):
    for n in range(1, 11):
        lhs, is_pretty = check_pretty(alpha_sqrt2, m, n, k)
        results_sqrt2.append((m, n, lhs, is_pretty))

for m, n, lhs, is_pretty in results_sqrt2:
    if is_pretty:
        print(f"Found pretty pair for sqrt(2): ({m}, {n}). Value: {lhs}")

print(f"\n--- Testing with alpha = pi ---")
results_pi = []
for m in range(1, 11):
    for n in range(1, 11):
        lhs, is_pretty = check_pretty(alpha_pi, m, n, k)
        results_pi.append((m, n, lhs, is_pretty))

for m, n, lhs, is_pretty in results_pi:
    if is_pretty:
        print(f"Found pretty pair for pi: ({m}, {n}). Value: {lhs}")

# Prepare data for note writing
print("\n--- Raw data summary ---")
print("Sqrt(2) Results (m, n, Value, Is_Pretty):")
for res in results_sqrt2:
    print(res)

print("\nPi Results (m, n, Value, Is_Pretty):")
for res in results_pi:
    print(res)

